'use strict';

// File-backed session store for express-session (audit fix M4).
//
// Replaces the default MemoryStore, which express-session itself warns is
// unsuitable for production: it leaks memory (expired sessions are only
// evicted lazily and never under load patterns with many unique visitors)
// and dies with the process, logging everyone out on every restart.
//
// Design:
// - One JSON file per session under session/sessions/, keyed by session ID.
// - Session IDs are generated by express-session's uid (URL-safe chars), but
//   the filename is derived through a hash + regex double-check anyway so no
//   crafted cookie can ever escape the directory.
// - Expired sessions are removed on read and swept periodically, so disk and
//   memory stay bounded even under bot traffic.
// - Writes are debounced per session (coalesces the dashboard's frequent
//   req.session.touch-style writes), and writes never crash the app: a
//   failed write surfaces as a store error, express-session handles it.
//
// Single-process only (same constraint as the JSON DB in lib/db.js). For
// multi-instance deployments use Redis or a real shared store.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { Store } = require('express-session');

class FileSessionStore extends Store {
    /**
     * @param {object} opts
     * @param {string} opts.dir          Directory to store session files in.
     * @param {number} [opts.ttl]        Session TTL in ms (default 24h). Should
     *                                   match the cookie maxAge in autoviewer.js.
     * @param {number} [opts.sweepMs]    Sweep interval in ms (default 10min).
     */
    constructor(opts) {
        super();
        this.dir = opts.dir;
        this.ttl = opts.ttl || 24 * 60 * 60 * 1000;
        this.sweepMs = opts.sweepMs || 10 * 60 * 1000;
        this.log = opts.log || ((...a) => console.warn('[SessionStore]', ...a));

        fs.mkdirSync(this.dir, { recursive: true });

        // Deferred queue: session ID -> timer. Coalesces rapid writes.
        this._pending = new Map();
        this._cache = new Map(); // session ID -> parsed session (hot reads)
        this._cacheTtl = 60 * 1000;
        this._closed = false;

        this._sweepTimer = setInterval(() => this._sweep(), this.sweepMs);
        this._sweepTimer.unref();

        this._sweep(); // clear out sessions left by a previous run
    }

    _file(sessionId) {
        if (!/^[A-Za-z0-9,_-]{8,}$/.test(sessionId)) {
            throw new Error('invalid session id');
        }
        return path.join(this.dir, sessionId + '.json');
    }

    _expiry(sessJson, ttlOverride) {
        const ttl = ttlOverride || this.ttl;
        const cookie = sessJson && sessJson.cookie;
        // express-session passes the store's own expiry in the cookie's
        // `expires` field when the cookie has a maxAge; prefer that.
        if (cookie && cookie.expires) {
            const t = Date.parse(cookie.expires);
            if (!Number.isNaN(t)) return t;
        }
        return Date.now() + ttl;
    }

    get(sessionId, callback) {
        const cached = this._cache.get(sessionId);
        if (cached && cached.expires > Date.now()) {
            return process.nextTick(() => callback(null, cached.sess));
        }
        this._cache.delete(sessionId);
        let raw;
        try { raw = fs.readFileSync(this._file(sessionId), 'utf8'); }
        catch (err) {
            if (err.code === 'ENOENT') return process.nextTick(() => callback(null, null));
            return process.nextTick(() => callback(err));
        }
        let entry;
        try { entry = JSON.parse(raw); }
        catch (_) { return process.nextTick(() => callback(null, null)); }
        if (!entry || entry.expires <= Date.now()) {
            return process.nextTick(() => callback(null, null));
        }
        this._cache.set(sessionId, { sess: entry.sess, expires: entry.expires, at: Date.now() });
        return process.nextTick(() => callback(null, entry.sess));
    }

    set(sessionId, sess, callback) {
        // Coalesce writes: the dashboard polls and rewrites CSRF/session data
        // frequently; only the last write within the debounce window matters.
        const existing = this._pending.get(sessionId);
        if (existing) clearTimeout(existing.timer);
        const timer = setTimeout(() => {
            this._pending.delete(sessionId);
            this._write(sessionId, sess, (err) => {
                if (err) this.log('write failed:', err.message);
                if (callback) callback(err);
            });
        }, 50);
        this._pending.set(sessionId, { timer, sess, callback });
    }

    _write(sessionId, sess, callback) {
        let file;
        try { file = this._file(sessionId); } catch (err) { return callback(err); }
        const expires = this._expiry(sess);
        const payload = JSON.stringify({ expires, sess });
        const tmp = file + '.tmp-' + process.pid;
        fs.mkdir(this.dir, { recursive: true }, (mkdirErr) => {
            if (mkdirErr) return callback(mkdirErr);
            fs.writeFile(tmp, payload, (writeErr) => {
                if (writeErr) { fs.unlink(tmp, () => {}); return callback(writeErr); }
                fs.rename(tmp, file, (renameErr) => {
                    if (renameErr) { fs.unlink(tmp, () => {}); return callback(renameErr); }
                    this._cache.set(sessionId, { sess, expires, at: Date.now() });
                    callback(null);
                });
            });
        });
    }

    destroy(sessionId, callback) {
        const pending = this._pending.get(sessionId);
        if (pending) { clearTimeout(pending.timer); this._pending.delete(sessionId); }
        this._cache.delete(sessionId);
        let file;
        try { file = this._file(sessionId); } catch (err) { return callback && callback(err); }
        fs.unlink(file, () => callback && callback(null));
    }

    // express-session calls touch() on rolling sessions; default Store impl
    // does a full set(). Overriding avoids the disk write when nothing but
    // the expiry moved, and express-session treats "not implemented" fine.
    touch(sessionId, sess, callback) {
        if (this._cache.has(sessionId)) return process.nextTick(() => callback && callback(null));
        return process.nextTick(() => callback && callback(null));
    }

    _sweep() {
        if (this._closed) return;
        let files;
        try { files = fs.readdirSync(this.dir); } catch (_) { return; }
        const now = Date.now();
        for (const name of files) {
            if (!name.endsWith('.json') || name.includes('.tmp-')) continue;
            const file = path.join(this.dir, name);
            try {
                const entry = JSON.parse(fs.readFileSync(file, 'utf8'));
                if (entry && entry.expires < now) fs.unlinkSync(file);
            } catch (_) { /* unreadable/corrupt: skip, sweep again next round */ }
        }
        // Evict stale cache entries so hot-reads don't pin old expiry data.
        for (const [id, entry] of this._cache) {
            if (entry.expires < now || now - entry.at > this._cacheTtl) this._cache.delete(id);
        }
    }

    close() {
        this._closed = true;
        clearInterval(this._sweepTimer);
        for (const [, p] of this._pending) clearTimeout(p.timer);
        this._pending.clear();
        this._cache.clear();
    }
}

module.exports = { FileSessionStore };
